--
-- Name: solution_proposals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.solution_proposals (
    id bigint NOT NULL,
    abstract_text text,
    created_at timestamp(6) without time zone,
    estimated_budget double precision,
    estimated_timeline_months integer,
    faculty_review_remarks text,
    methodology text,
    proposed_solution text,
    status character varying(30),
    title character varying(255) NOT NULL,
    updated_at timestamp(6) without time zone,
    complaint_id bigint NOT NULL,
    faculty_mentor_id bigint,
    student_lead_id bigint,
    university_id bigint NOT NULL,
    CONSTRAINT solution_proposals_status_check CHECK (((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'SUBMITTED'::character varying, 'UNDER_FACULTY_REVIEW'::character varying, 'APPROVED_BY_FACULTY'::character varying, 'REJECTED'::character varying, 'ACCEPTED_FOR_PROJECT'::character varying])::text[])))
);


--
-- Name: solution_proposals_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.solution_proposals ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.solution_proposals_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


